let particles = [];
let quasarMode = true;

class Trail {
  constructor(maxLength) {
    this.maxLength = maxLength;
    this.points = [];
  }

  addPoint(x, y) {
    this.points.push(createVector(x, y));
    if (this.points.length > this.maxLength) {
      this.points.shift();
    }
  }

  display(col, life) {
    if (this.points.length < 2) return;
    noFill();
    for (let i = 1; i < this.points.length; i++) {
      let a = map(i, 0, this.points.length, 10, life * 0.8);
      stroke(red(col), green(col), blue(col), a);
      strokeWeight(map(i, 0, this.points.length, 1, 3.5));
      line(this.points[i-1].x, this.points[i-1].y, this.points[i].x, this.points[i].y);
    }
  }
}

class SupernovaParticle {
  constructor(x, y) {
    this.position = createVector(x, y);
    this.velocity = p5.Vector.random2D().mult(random(2, 6));
    this.lifeSpan = 255;
    this.trail = new Trail(24);
    let h = (typeof chordHue !== 'undefined' ? chordHue : random(180, 260)) + random(-30, 30);
    this.col = color(`hsl(${Math.round((h + 360) % 360)}, 85%, 65%)`);
  }

  update() {
    this.position.add(this.velocity);
    this.velocity.mult(0.985);
    this.lifeSpan -= 2.2;
    this.trail.addPoint(this.position.x, this.position.y);
  }

  display() {
    this.trail.display(this.col, this.lifeSpan);
    noStroke();
    fill(red(this.col), green(this.col), blue(this.col), this.lifeSpan);
    circle(this.position.x, this.position.y, 4);
  }

  isOffScreen() {
    return (this.position.x < 0 || this.position.x > width || 
            this.position.y < 0 || this.position.y > height);
  }
}

function setup() {
  createCanvas(windowWidth, windowHeight);
  quasarMode = true;
  for (let i = 0; i < 50; i++) {
    let p = new SupernovaParticle(random(width * 0.2, width * 0.8), random(height * 0.2, height * 0.8));
    particles.push(p);
  }
}

function draw() {
  background(10, 12, 18, 35);

  if (particles.length < 25 || quasarMode) {
    emitQuasarLight();
  }

  for (let i = particles.length - 1; i >= 0; i--) {
    particles[i].update();
    particles[i].display();
    if (particles[i].isOffScreen() || particles[i].lifeSpan <= 0) {
      particles.splice(i, 1);
    }
  }
}

function emitQuasarLight() {
  let cx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : width / 2 + Math.sin(frameCount * 0.03) * width * 0.35);
  let cy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : height / 2 + Math.cos(frameCount * 0.02) * height * 0.35);
  let burst = (window.isBeat || Math.random() < 0.2) ? 3 : 1;
  for (let b = 0; b < burst; b++) {
    particles.push(new SupernovaParticle(cx + random(-10, 10), cy + random(-10, 10)));
  }
}

function mousePressed() {
  emitQuasarLight();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

